<?php
require __DIR__.'/../config/app.php';$me=require_role('committee');ensure_committee_schema();$rows=[];
try{$q=db()->prepare('SELECT e.id,e.title,e.category,e.description,e.event_date,e.event_time,e.venue,e.capacity,COUNT(a.id) applications FROM committee_event_assignments cea JOIN events e ON e.id=cea.event_id LEFT JOIN event_applications a ON a.event_id=e.id WHERE cea.committee_user_id=? GROUP BY e.id ORDER BY e.event_date,e.title');$q->execute([$me['id']]);$rows=$q->fetchAll();}catch(Throwable $t){}
$pageTitle='Assigned Events';$activePage='events';$bodyClass='dashboard-page committee-page';$hideSiteNav=true;require __DIR__.'/../includes/header.php';
?><div class="dash-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content committee-content"><header class="admin-page-heading"><div><span class="admin-eyebrow">COMMITTEE WORKSPACE</span><h1>Assigned Events</h1><p>These are the events an administrator assigned to your account.</p></div></header><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('calendar')?></span><div><h2>Events <span class="admin-count"><?=count($rows)?></span></h2><p>You can view their details and review related applications.</p></div></div><?php if($rows):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Event</th><th>Category</th><th>Date & time</th><th>Venue</th><th>Capacity</th><th>Applications</th></tr></thead><tbody><?php foreach($rows as $event):?><tr><td><strong><?=e($event['title'])?></strong><?php if($event['description']):?><small><?=e(mb_strimwidth($event['description'],0,130,'…'))?></small><?php endif;?></td><td><span class="pill <?=e($event['category'])?>"><?=e(ucfirst($event['category']))?></span></td><td><?=date('d M Y',strtotime($event['event_date']))?><small><?=date('g:i A',strtotime($event['event_time']))?></small></td><td><?=e($event['venue'])?></td><td><?=(int)$event['capacity']?></td><td><a href="<?=url('committee/applications.php?event_id='.$event['id'])?>"><?=(int)$event['applications']?> · Review</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No events are assigned to your account yet. Ask an administrator to assign an event.</div><?php endif;?></section></main></div><?php require __DIR__.'/../includes/footer.php';
